  idempotency_key?: string | null;
  is_enabled: boolean;
  page_id: string;
}): Promise<CallToolResult<{ [key: string]: unknown; } | { error: {
  code?: string;
  commit_status?: string;
  // Optional upstream error details.
  details?: unknown;
